        private static string Name(Type type)
        {
            return type == null ? "<null>" : type.AssemblyQualifiedName;
        }

        private static string Value(object value)
        {
            if (value == null) return "<null>";
            if (value is Type type) return "Type:" + Name(type);
            if (value is IList values)
            {
                var items = new List<string>();
                foreach (object item in values)
                {
                    if (item is CustomAttributeTypedArgument argument)
                        items.Add(Name(argument.ArgumentType) + "=" + Value(argument.Value));
                    else items.Add(Value(item));
                }
                return "List[" + string.Join(";", items) + "]";
            }
            if (value is string text) return "String:" + text;
            if (value is IFormattable formattable)
                return Name(value.GetType()) + ":" + formattable.ToString(null, CultureInfo.InvariantCulture);
            return Name(value.GetType()) + ":" + value.ToString();
        }

        private static void Attributes(CurrentCrashImage image, Observation data, string owner, IList<CustomAttributeData> attributes)
        {
            data.rows.Add(owner + "|AttributeCount=" + attributes.Count);
            foreach (CustomAttributeData attribute in attributes)
            {
                ParameterInfo[] declared = attribute.Constructor.GetParameters();
                data.rows.Add(owner + "|Attribute=" + Name(attribute.AttributeType)
                    + "|CtorSignature=" + Name(attribute.AttributeType) + "::.ctor("
                    + string.Join(";", declared.Select(p => Name(p.ParameterType))) + ")"
                    + "|CtorModule=" + attribute.Constructor.Module.Name);
                for (int i = 0; i < attribute.ConstructorArguments.Count; ++i)
                {
                    CustomAttributeTypedArgument argument = attribute.ConstructorArguments[i];
                    data.rows.Add(owner + "|Arg=" + i + "|Declared=" + Name(declared[i].ParameterType)
                        + "|Reflected=" + Name(argument.ArgumentType) + "|Value=" + Value(argument.Value));
                }
                foreach (CustomAttributeNamedArgument argument in attribute.NamedArguments)
                {
                    data.rows.Add(owner + "|Named=" + argument.MemberName + "|Field=" + argument.IsField
                        + "|Reflected=" + Name(argument.TypedValue.ArgumentType)
                        + "|Value=" + Value(argument.TypedValue.Value));
                }
            }
        }

        private static void Parameter(CurrentCrashImage image, Observation data, string owner, ParameterInfo parameter)
        {
            data.rows.Add(owner + "|Name=" + parameter.Name + "|TokenIdentity=" + image.Key(parameter.MetadataToken)
                + "|Position=" + parameter.Position + "|Type=" + Name(parameter.ParameterType)
                + "|Flags=" + (int)parameter.Attributes + "|HasDefault=" + parameter.HasDefaultValue
                + "|RawDefault=" + Value(parameter.RawDefaultValue) + "|Default=" + Value(parameter.DefaultValue));
            Attributes(image, data, owner, parameter.GetCustomAttributesData());
        }

        private static void Method(CurrentCrashImage image, Observation data, MethodBase method)
        {
            string owner = method.DeclaringType.FullName + "|Method=" + method.Name
                + "|TokenIdentity=" + image.Key(method.MetadataToken);
            data.rows.Add(owner + "|Flags=" + (int)method.Attributes + "|Impl=" + (int)method.GetMethodImplementationFlags());
            Attributes(image, data, owner, method.GetCustomAttributesData());
            foreach (ParameterInfo parameter in method.GetParameters())
                Parameter(image, data, owner + "|Ordinary", parameter);
            if (method is MethodInfo info) Parameter(image, data, owner + "|Return", info.ReturnParameter);
            if (method.IsGenericMethod)
            {
                foreach (Type generic in method.GetGenericArguments())
                {
                    data.rows.Add(owner + "|Generic=" + generic.Name + "|Position=" + generic.GenericParameterPosition
                        + "|Flags=" + (int)generic.GenericParameterAttributes);
                    foreach (Type constraint in generic.GetGenericParameterConstraints())
                        data.rows.Add(owner + "|Constraint=" + Name(constraint));
                }
            }
            MethodBody body = method.GetMethodBody();
            if (body == null) { data.rows.Add(owner + "|Body=<null>"); return; }
            data.rows.Add(owner + "|LocalSignature=" + image.Key(body.LocalSignatureMetadataToken)
                + "|InitLocals=" + body.InitLocals + "|MaxStack=" + body.MaxStackSize
                + "|" + image.PortableCil(body));
            foreach (LocalVariableInfo local in body.LocalVariables)
                data.rows.Add(owner + "|Local=" + local.LocalIndex + "|Type=" + Name(local.LocalType) + "|Pinned=" + local.IsPinned);
            foreach (ExceptionHandlingClause clause in body.ExceptionHandlingClauses)
            {
                string suffix = clause.Flags == ExceptionHandlingClauseOptions.Clause ? "|Catch=" + Name(clause.CatchType)
                    : clause.Flags == ExceptionHandlingClauseOptions.Filter ? "|Filter=" + clause.FilterOffset : "";
                data.rows.Add(owner + "|EH=" + (int)clause.Flags + "|TryOffset=" + clause.TryOffset
                    + "|TryLength=" + clause.TryLength + "|HandlerOffset=" + clause.HandlerOffset
                    + "|HandlerLength=" + clause.HandlerLength + suffix);
            }
        }

        static Observation ObserveWholeMetadata(CurrentCrashImage image)
        {
            Type anchor = typeof(HLCrashReport);
            Assembly assembly = anchor.Assembly;
            var data = new Observation();
            data.rows.Add("Assembly=" + assembly.FullName);
            data.rows.Add("Module=" + anchor.Module.Name);
            const BindingFlags flags = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.Static | BindingFlags.DeclaredOnly;
            Type[] types = assembly.GetTypes();
            data.rows.Add("CompleteTypeCount=" + types.Length);
            foreach (Type type in types)
            {
                string owner = type.FullName + "|TypeTokenIdentity=" + image.Key(type.MetadataToken);
                data.rows.Add(owner + "|Flags=" + (int)type.Attributes + "|Base=" + Name(type.BaseType)
                    + "|Declaring=" + Name(type.DeclaringType));
                Attributes(image, data, owner, type.GetCustomAttributesData());
                foreach (Type contract in type.GetInterfaces()) data.rows.Add(owner + "|Interface=" + Name(contract));
                foreach (FieldInfo field in type.GetFields(flags))
                {
                    string fieldOwner = owner + "|Field=" + field.Name + "|FieldTokenIdentity=" + image.Key(field.MetadataToken);
                    data.rows.Add(fieldOwner + "|Flags=" + (int)field.Attributes + "|FieldType=" + Name(field.FieldType));
                    if ((field.Attributes & FieldAttributes.HasDefault) != 0)
                        data.rows.Add(fieldOwner + "|RawConstant=" + Value(field.GetRawConstantValue()));
                    Attributes(image, data, fieldOwner, field.GetCustomAttributesData());
                }
                foreach (ConstructorInfo constructor in type.GetConstructors(flags)) Method(image, data, constructor);
                foreach (MethodInfo method in type.GetMethods(flags)) Method(image, data, method);
                foreach (PropertyInfo property in type.GetProperties(flags))
                {
                    string propertyOwner = owner + "|Property=" + property.Name + "|PropertyTokenIdentity=" + image.Key(property.MetadataToken);
                    data.rows.Add(propertyOwner + "|Flags=" + (int)property.Attributes + "|PropertyType=" + Name(property.PropertyType));
                    Attributes(image, data, propertyOwner, property.GetCustomAttributesData());
                }
                foreach (EventInfo eventInfo in type.GetEvents(flags))
                    data.rows.Add(owner + "|Event=" + eventInfo.Name + "|EventTokenIdentity=" + image.Key(eventInfo.MetadataToken)
                        + "|Flags=" + (int)eventInfo.Attributes + "|EventType=" + Name(eventInfo.EventHandlerType));
            }
            return data;
        }
