  void RequireAllAttributes(){var ordinals=new Dictionary<int,int>();int w=Coded(5,6,4,1,2,8,9,10,0,14,23,20,17,26,27,32,35,38,39,40,42,44,43),cw=Coded(3,6,10);for(int i=1;i<=counts[12];i++){int at=At(12,i),parent=Token(Read(at,w),5,6,4,1,2,8,9,10,0,14,23,20,17,26,27,32,35,38,39,40,42,44,43),n;ordinals.TryGetValue(parent,out n);var all=AttributeParent(parent);Need(n<all.Count,"whole physical/loaded CA parent order");int ct=Read(at+w,cw);Need((ct&7)==2||(ct&7)==3,"genuine physical CA constructor kind");int tok=(((ct&7)==2?6:10)<<24)|(ct>>3);Need(module.ResolveMethod(tok)==all[n].Constructor,"exact physical/reflected attribute constructor binding");RequireResolved(tok);ordinals[parent]=n+1;}foreach(var item in ordinals)Need(AttributeParent(item.Key).Count==item.Value,"complete physical/loaded CA counts on every present parent");}
