  internal static string JsonString(string text){var b=new System.Text.StringBuilder("\"");foreach(char c in text){switch(c){case '"':b.Append("\\\"");break;case '\\':b.Append("\\\\");break;case '\b':b.Append("\\b");break;case '\f':b.Append("\\f");break;case '\n':b.Append("\\n");break;case '\r':b.Append("\\r");break;case '\t':b.Append("\\t");break;default:if(c<32||c>=128)b.Append("\\u"+((int)c).ToString("x4"));else b.Append(c);break;}}return b.Append('"').ToString();}
  internal string PortableCil(MethodBody body){byte[] code=body.GetILAsByteArray(),literal=(byte[])code.Clone();var cells=new List<string>();for(int at=0;at<code.Length;){int start=at,op=code[at++];if(op==254){Need(at<code.Length,"whole two-byte CIL opcode");op=(op<<8)|code[at++];}OpFact fact;Need(Ops.TryGetValue(op,out fact),"exact owned opcode vocabulary");int n=fact.width;if(n<0){Need(at<=code.Length-4,"complete switch count");int count=BitConverter.ToInt32(code,at);Need(count>=0&&count<=(code.Length-at-4)/4,"whole switch table");n=4+count*4;}Need(at<=code.Length-n,"whole opcode operand");if(fact.token){Need(n==4,"exact four-byte token operand");int token=BitConverter.ToInt32(code,at);string key;if(fact.userString){Need(((uint)token>>24)==112,"genuine UserString token");key="UserString:"+module.ResolveString(token);}else{RequireResolved(token);key=Key(token);}for(int i=0;i<4;i++)literal[at+i]=0;cells.Add("{\"offset\":"+at+",\"scoped_key\":"+JsonString(key)+"}");}at+=n;Need(at>start,"strict instruction progress");}return"CILLiteral="+Hex(literal)+"|Cells=["+string.Join(",",cells)+"]";}
